import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {validateUserPreset,parseUserPreset,serializeUserPreset,loadUserPreset,capturePresetFromDom,MAX_PRESET_BYTES,ENGINE_FIELDS,AUDIO_FIELDS,presetFilename} from './user-presets.mjs';
const factory=JSON.parse(await readFile(new URL('./presets/d-major-drift.json',import.meta.url),'utf8'));const preset={format:'cortex65-preset',version:1,name:'Boundary Patch',engine:{...factory.engine},audio:{...factory.audio,orbitEnabled:false,orbitRate:.07,orbitDepth:.7}};
assert.deepEqual(parseUserPreset(serializeUserPreset(preset)),preset);const varied=structuredClone(preset);Object.assign(varied.engine,{mode:'modular',coupling:8,noise:2,drift:2,projection:-1,pulseMode:'rain',pulseEnabled:true,pulseRate:12,pulseJitter:1,pulseStrength:0,attack:.03,decay:4,sustain:1,release:5});Object.assign(varied.audio,{tuningMode:'free',root:1046.503,scale:'fifths',detune:100,tone:0,space:1,output:1,reverb:1,reverbSize:0,spread:1,variation:1,octaves:3,voiceLimit:16,binaural:true,droneEnabled:true,difference:50});assert.deepEqual(parseUserPreset(serializeUserPreset(varied)),varied);
for(let iteration=0;iteration<6;iteration++){const boundary=structuredClone(preset);for(const [section,schema] of [['engine',ENGINE_FIELDS],['audio',AUDIO_FIELDS]])for(const [key,rule]of Object.entries(schema))boundary[section][key]=rule.kind==='number'?(iteration%2?rule.min:rule.max):rule.kind==='choice'?rule.values[iteration%rule.values.length]:!!(iteration%2);if(boundary.audio.orbitEnabled)boundary.audio.binaural=false;assert.deepEqual(parseUserPreset(serializeUserPreset(boundary)),boundary);}
let mutations=0;const adapter={slider(){mutations++;},choice(){mutations++;},toggle(){mutations++;}};
for(const change of[p=>delete p.engine.drift,p=>p.audio.root=1,p=>p.audio.octaves=1.5,p=>p.audio.binaural='true',p=>p.audio.output=null,p=>p.version=2,p=>p.format='wrong',p=>delete p.format,p=>p.version='1',p=>p.name='',p=>p.name='x'.repeat(81),p=>p.engine.noise=Infinity,p=>p.engine.mode='wrong']){const invalid=structuredClone(preset);change(invalid);assert.throws(()=>loadUserPreset(JSON.stringify(invalid),adapter));assert.equal(mutations,0);}
assert.throws(()=>loadUserPreset('{broken',adapter));assert.throws(()=>loadUserPreset(' '.repeat(MAX_PRESET_BYTES+1),adapter),/256 KiB/);assert.throws(()=>parseUserPreset('😀'.repeat(MAX_PRESET_BYTES/3)),/256 KiB/);assert.equal(presetFilename('../A/B:Preset'),'..-A-B-Preset.cortex65.json');assert.equal(mutations,0);const epsilon=structuredClone(preset);epsilon.engine.drift=2.0000000000000004;assert.equal(validateUserPreset(epsilon).engine.drift,2);epsilon.engine.drift=2.000001;assert.throws(()=>validateUserPreset(epsilon));
const dirty=JSON.parse(JSON.stringify(preset).replace('"engine":{','"__proto__":{"polluted":true},"engine":{"constructor":{"prototype":{"polluted":true}},'));const clean=validateUserPreset(dirty);assert.equal(Object.hasOwn(clean,'__proto__'),false);assert.equal(Object.hasOwn(clean.engine,'constructor'),false);assert.equal({}.polluted,undefined);assert.deepEqual(clean,preset);
assert.deepEqual(parseUserPreset(JSON.stringify(factory)),preset.name===factory.name?preset:{...preset,name:factory.name});
const numeric={...preset.engine,...preset.audio},values={root:String(factory.audio.root),scale:factory.audio.scale,'voice-limit':String(factory.audio.voiceLimit),octaves:String(factory.audio.octaves),'pulse-mode':'regional'},selected={modes:{mode:'islands'},projections:{projection:'0'},'tuning-modes':{tuning:'locked'}};const doc={getElementById(id){return{value:values[id],getAttribute:()=> 'false',querySelector:()=>({dataset:selected[id]})};}};const captured=capturePresetFromDom(doc,numeric,'Before First Click');assert.equal(captured.engine.mode,'islands');assert.equal(captured.engine.projection,0);assert.equal(captured.audio.tuningMode,'locked');assert.equal(Object.keys(captured.engine).length,14);assert.equal(Object.keys(captured.audio).length,19);
loadUserPreset(serializeUserPreset(varied),adapter);assert.equal(mutations,33);
const html=await readFile(new URL('./index.html',import.meta.url),'utf8');for(const id of['preset-name','preset-save','preset-load','preset-file'])assert.ok(html.includes('id="'+id+'"'),'real preset UI '+id);
console.log(JSON.stringify({ok:true,completeMusicalFields:33,nonDefaultRoundTrip:true,boundaries:true,epsilonClamp:true,invalidAtomicity:true,malformedOversizeRejected:true,prototypeKeysCleaned:true,defaultDomCapture:true,factoryLegacySupported:true,realSaveLoadControls:true},null,2));

const legacy=structuredClone(preset);for(const key of ['orbitEnabled','orbitRate','orbitDepth'])delete legacy.audio[key];assert.deepEqual(parseUserPreset(JSON.stringify(legacy)),preset);for(const key of ['orbitEnabled','orbitRate','orbitDepth']){const partial=structuredClone(legacy);partial.audio[key]=preset.audio[key];assert.throws(()=>validateUserPreset(partial),/Incomplete/);}const orbit=structuredClone(preset);Object.assign(orbit.audio,{orbitEnabled:true,binaural:true,orbitRate:.5,orbitDepth:1});assert.equal(validateUserPreset(orbit).audio.binaural,false);for(const change of[p=>p.audio.orbitRate=.009,p=>p.audio.orbitDepth=1.01,p=>p.audio.orbitEnabled=1]){const invalid=structuredClone(orbit);change(invalid);assert.throws(()=>validateUserPreset(invalid));}

assert.ok(html.includes('id="orbitRate" type="range" min=".01" max=".5" step=".001" value=".07"'));assert.ok(html.includes('id="orbitDepth" type="range" min="0" max="1" step=".01" value=".7"'));
